<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){exit("CLI only\n");}
$_SERVER['REMOTE_ADDR']='127.0.0.1';$_SERVER['REQUEST_METHOD']='GET';require dirname(__DIR__).'/htdocs/app/bootstrap.php';
$action=$argv[1]??'';if(!in_array($action,['seed','reset'],true)){exit("Usage: php tools/demo_data.php seed|reset\n");}
if(cfg('app_env')!=='demo' || !cfg('demo_mode',false) || getenv('HASAD_DEMO_ALLOW_RESET')!=='yes'){throw new RuntimeException('Refusing: dedicated demo environment and HASAD_DEMO_ALLOW_RESET=yes are required.');}
$personas=cfg('demo_personas',[]);$supplierPhone=phone((string)($personas['supplier']['phone']??''));$buyerPhone=phone((string)($personas['buyer']['phone']??''));$adminEmail=strtolower((string)($personas['admin']['email']??''));$supplierPass=(string)getenv('HASAD_DEMO_SUPPLIER_PASSWORD');$buyerPass=(string)getenv('HASAD_DEMO_BUYER_PASSWORD');$adminPass=(string)getenv('HASAD_DEMO_ADMIN_PASSWORD');
if($supplierPhone===$buyerPhone || !filter_var($adminEmail,FILTER_VALIDATE_EMAIL) || min(strlen($supplierPass),strlen($buyerPass),strlen($adminPass))<12){throw new RuntimeException('Configure unique persona identifiers and passwords of at least 12 characters.');}
$tables=['journal_lines','journals','transfer_register','settlements','payments','shipments','stock_movements','production_jobs','orders','batches','supply_requests','tickets','expenses','tasks','projects','procurement','attendance','parties','otp_challenges','rate_events','audit_log','users'];
$reset=function()use($tables):void{Db::run('SET FOREIGN_KEY_CHECKS=0');try{foreach($tables as $table){Db::run('DELETE FROM `'.$table.'`');}Db::run("UPDATE settings SET setting_value=CASE setting_key WHEN 'demo_data' THEN '0' WHEN 'demo_seed_version' THEN '0' ELSE setting_value END WHERE setting_key IN ('demo_data','demo_seed_version')");}finally{Db::run('SET FOREIGN_KEY_CHECKS=1');}};
$reset();if($action==='reset'){echo "Synthetic demo records reset.\n";exit(0);}
Db::tx(function()use($supplierPhone,$buyerPhone,$adminEmail,$supplierPass,$buyerPass,$adminPass):void{
 $admin=Db::insert("INSERT INTO users(name,email,password_hash,role) VALUES('مدير العرض التدريبي',?,?,'super_admin')",[$adminEmail,password_hash($adminPass,PASSWORD_DEFAULT)]);
 $supplier=Db::insert("INSERT INTO users(name,phone,password_hash,role,account_type,verified_at) VALUES('مورد تدريبي',?,?,'member','seller',UTC_TIMESTAMP())",[$supplierPhone,password_hash($supplierPass,PASSWORD_DEFAULT)]);
 $buyer=Db::insert("INSERT INTO users(name,phone,password_hash,role,account_type,verified_at) VALUES('مصنع تدريبي',?,?,'member','buyer',UTC_TIMESTAMP())",[$buyerPhone,password_hash($buyerPass,PASSWORD_DEFAULT)]);
 $party=Db::insert("INSERT INTO parties(kind,name,phone,organization,governorate,address,verified,user_id) VALUES('seller','مورد تدريبي',?,'','Sharqia','عنوان تدريبي غير حقيقي',1,?)",[$supplierPhone,$supplier]);
 Db::run("UPDATE hubs SET address='مركز تدريبي — لا يمثل موقعاً حقيقياً',active=1 WHERE id=1");
 $forms=['baled','loose','chopped','processed'];$i=0;foreach(catalogue_materials() as $m){$i++;$code='DEMO-S-00'.$i;$request=Db::insert("INSERT INTO supply_requests(public_code,user_id,contact_name,contact_phone,material_id,quantity_g,governorate,location,handover,notes,contact_verified,status) VALUES(?,?,?,?,?,12000000,?,'موقع تدريبي','dropoff','بيانات صناعية للتدريب فقط',1,'inspected')",[$code,$supplier,'مورد تدريبي',$supplierPhone,$m['id'],['Sharqia','Dakahlia','Giza','Qena'][$i-1]]);$batch=Db::insert("INSERT INTO batches(code,request_id,supplier_id,hub_id,material_id,grade,subcategory,quantity_g,price_per_tonne,moisture_bp,inspection_notes,status,inspected_by) VALUES(?,?,?,?,?,'A',?,12000000,150000,1100,'فحص تدريبي اصطناعي','published',?)",['DEMO-B-00'.$i,$request,$party,1,$m['id'],$forms[$i-1],$admin]);stock_move($batch,'demo_seed',12000000,0,$code);}
 Db::run("INSERT INTO parties(kind,name,phone,organization,governorate,address,verified,user_id) VALUES('buyer','مصنع تدريبي',?,'مصنع تدريبي غير حقيقي','Cairo','عنوان تدريبي',1,?)",[$buyerPhone,$buyer]);
 foreach(['demo_data'=>'1','demo_seed_version'=>'20261119','launch_open'=>'1','instapay_account'=>'demo@instapay','contact_phone'=>$supplierPhone,'legal_name'=>'بيئة حصاد التدريبية','legal_address'=>'عنوان تدريبي'] as $k=>$v){Db::run('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',[$k,$v]);}
 audit('demo_seeded','settings',0,['version'=>'20261119','synthetic'=>true]);
});echo "Synthetic demo data seeded idempotently for three configured personas.\n";
